package dev.dydiscord;
import dev.dydiscord.config.*;
import dev.dydiscord.language.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.io.TempDir;
import org.junit.jupiter.params.*;
import org.junit.jupiter.params.provider.*;
import java.nio.file.*;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
class ConfigurationTest {
    @TempDir Path folder;
    @ParameterizedTest @ValueSource(strings={"https://discord.gg/example","https://discord.com/invite/Ab12-xy",""})void validInvites(String url){assertDoesNotThrow(()->Settings.validateInvite(url));}
    @ParameterizedTest @ValueSource(strings={"http://discord.gg/valid","https://discord.gg.evil/valid","https://evil@discord.gg/valid","https://discord.gg:443/valid","https://discord.gg/valid?x=1","https://discord.gg/valid#x","https://discord.com/invite/%41abc","https://discord.gg/valid/extra","https://discord.com/valid","https://discord.gg/abc\n"})void fakeInvites(String url){assertThrows(IllegalArgumentException.class,()->Settings.validateInvite(url));}
    @Test void initialSetupWaitsForCredentialsAndPrivateChannelWithCommandsDisabled()throws Exception{Configuration c=TestSupport.config(folder);assertTrue(c.active().settings().botEnabled());assertTrue(c.active().settings().consoleEnabled());assertTrue(c.active().settings().panelEnabled());assertTrue(c.active().settings().consoleChannel().isEmpty());assertFalse(c.active().settings().commandsEnabled());assertTrue(c.active().settings().token().isEmpty());}
    @Test void oldDefaultPrefixUpgradesWhileCustomPrefixesAndCommentsSurvive()throws Exception{Configuration c=TestSupport.config(folder);Files.writeString(folder.resolve("config.yml"),"prefix: '&7[&dDyDiscord&7]'\n# owner's comment\n");c.load();assertEquals("&7[&9DyDiscord&7]",c.active().settings().prefix());assertTrue(Files.readString(folder.resolve("config.yml")).contains("owner's comment"));assertEquals("&7[&9DyDiscord&7]",Configuration.read(folder.resolve("config.yml")).get("prefix"));Files.writeString(folder.resolve("config.yml"),"prefix: '&aCustom'\n");c.load();assertEquals("&aCustom",c.active().settings().prefix());}
    @Test void invalidReloadRetainsActiveSettings()throws Exception{Configuration c=TestSupport.config(folder);Settings old=c.active().settings();Files.writeString(folder.resolve("config.yml"),"lang: invalid\n");assertThrows(IllegalArgumentException.class,c::load);assertSame(old,c.active().settings());}
    @Test void futureSchemaCannotBeOverwritten()throws Exception{Configuration c=TestSupport.config(folder);Files.writeString(folder.resolve("config.yml"),"config-version: 9\n");assertThrows(IllegalArgumentException.class,()->c.change("config.yml","lang","tr"));assertTrue(Files.readString(folder.resolve("config.yml")).contains("9"));}
    @Test void atomicChangesPreserveCommentsAndCustomMessages()throws Exception{Configuration c=TestSupport.config(folder);Files.writeString(folder.resolve("config.yml"),Files.readString(folder.resolve("config.yml"))+"# owner's comment\n");c.change("config.yml","lang","tr");assertEquals("tr",c.active().settings().language());assertTrue(Files.readString(folder.resolve("config.yml")).contains("owner's comment"));c.change("bot.yml","console.commands.allowed-role-ids",List.of("123456789012345678"));assertTrue(Files.readString(folder.resolve("bot.yml")).contains("'123456789012345678'")||Files.readString(folder.resolve("bot.yml")).contains("\"123456789012345678\""));}
    @Test void invalidBoundsAndSameChannelsRejected()throws Exception{Configuration c=TestSupport.config(folder);for(int v:List.of(-1,0,100000))assertThrows(IllegalArgumentException.class,()->c.change("config.yml","linking.code-length",v));c.change("bot.yml","panel.channel-id","123456789012345678");assertThrows(IllegalArgumentException.class,()->c.change("bot.yml","console.channel-id","123456789012345678"));}
    @Test void malformedMessagesPreserveSnapshot()throws Exception{Configuration c=TestSupport.config(folder);var old=c.active();Files.writeString(folder.resolve("discord/messages_tr.yml"),"bad: [invalid");assertThrows(java.io.IOException.class,c::load);assertSame(old,c.active());}
    @Test void missingKeyFallsBackToBundledEnglish()throws Exception{Configuration c=TestSupport.config(folder);Files.writeString(folder.resolve("messages_tr.yml"),"no-permission: 'Yok'\n");c.load();assertEquals("&7Your Minecraft account is not linked to a Discord account.",c.active().messages().get(false,"tr","not-linked"));}
    @Test void placeholderMismatchRejected()throws Exception{Configuration c=TestSupport.config(folder);Files.writeString(folder.resolve("messages_tr.yml"),"invite: 'Join {evil}'\n");assertThrows(java.io.IOException.class,c::load);}
    @Test void discordComponentAndRenderedTitleLimitsValidatedBeforeReload()throws Exception{Configuration c=TestSupport.config(folder);var original=c.active();Files.writeString(folder.resolve("discord/messages_en.yml"),"link: '"+"a".repeat(81)+"'\n");assertThrows(java.io.IOException.class,c::load);assertSame(original,c.active());Files.writeString(folder.resolve("discord/messages_en.yml"),"panel-title: '{server_name} "+"a".repeat(240)+"'\n");assertThrows(IllegalArgumentException.class,c::load);assertSame(original,c.active());}
    @Test void failedSecurityValidationPreservesBothFileAndSnapshot()throws Exception{Configuration c=TestSupport.config(folder);String before=Files.readString(folder.resolve("bot.yml"));Settings active=c.active().settings();assertThrows(java.io.IOException.class,()->c.change("bot.yml","console.enabled",true,next->{throw new IllegalStateException("Unavailable permission check");}));assertEquals(before,Files.readString(folder.resolve("bot.yml")));assertSame(active,c.active().settings());}
    @Test void failedAtomicWriteCannotReplaceDirectory()throws Exception{Path directory=folder.resolve("target");Files.createDirectories(directory);Files.writeString(directory.resolve("preserve"),"original");assertThrows(java.io.IOException.class,()->Configuration.atomicWrite(directory,"replacement"));assertEquals("original",Files.readString(directory.resolve("preserve")));}
    @Test void languagesAndPlaceholdersMatchAcrossEverySurface()throws Exception{for(String surface:List.of("","discord/")){Map<String,Object> en=resource(surface+"messages_en.yml"),tr=resource(surface+"messages_tr.yml");assertEquals(en.keySet(),tr.keySet());for(String key:en.keySet())assertEquals(Messages.placeholders((String)en.get(key)),Messages.placeholders((String)tr.get(key)),key);}}
    private Map<String,Object> resource(String file)throws Exception{try(var in=getClass().getResourceAsStream("/"+file)){return Configuration.parse(new String(in.readAllBytes(),java.nio.charset.StandardCharsets.UTF_8));}}
    @ParameterizedTest @CsvSource({"auto,auto,tr_TR,tr","auto,auto,en_US,en","auto,auto,de_DE,en","auto,tr,en_US,tr","en,tr,tr_TR,en","tr,en,en_US,tr","auto,en,tr_TR,en"})void languagePriority(String global,String preference,String locale,String result){assertEquals(result,Messages.language(global,preference,locale));}
    @Test void missingLocaleAndConsoleUseEnglish(){assertEquals("en",Messages.language("auto",null,null));}
    @Test void externalValuesCannotInjectColorOrMention()throws Exception{var c=TestSupport.config(folder);String rendered=c.active().messages().render(false,"en","account",Map.of("name","&cAlice§c","discord","123","date","now"));assertTrue(rendered.contains("&cAlice"));assertFalse(rendered.contains("Alice§c"));assertFalse(Messages.safeDiscord("@everyone `**").contains("@everyone"));}
    @Test void yamlDuplicatesAndNumericSnowflakesRejected(){assertThrows(java.io.IOException.class,()->Configuration.parse("lang: en\nlang: tr"));assertThrows(IllegalArgumentException.class,()->Settings.read(Map.of(),Map.of("guild-id",123456789012345678L),null));}
}
